CREATE OR REPLACE VIEW public.product_commission_preview WITH (security_invoker = true) AS SELECT p.id,p.name,p.product_type,p.price,p.app_fee,p.nutritionist_fee,p.tax_percentage,p.pix_fee_percentage,p.credit_fee_percentage,p.debit_fee_percentage,ROUND(p.price*p.pix_fee_percentage/100,2) AS pix_gateway_fee,ROUND((p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.pix_fee_percentage/100))*p.tax_percentage/100,2) AS pix_tax,ROUND(p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.pix_fee_percentage/100)-((p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.pix_fee_percentage/100))*p.tax_percentage/100),2) AS pix_commission_base,ROUND((p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.pix_fee_percentage/100)-((p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.pix_fee_percentage/100))*p.tax_percentage/100))*p.commission_coach/100,2) AS pix_coach_commission,ROUND(p.price*p.credit_fee_percentage/100,2) AS credit_gateway_fee,ROUND((p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.credit_fee_percentage/100))*p.tax_percentage/100,2) AS credit_tax,ROUND((p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.credit_fee_percentage/100)-((p.price-p.app_fee-COALESCE(p.nutritionist_fee,0)-(p.price*p.credit_fee_percentage/100))*p.tax_percentage/100))*p.commission_coach/100,2) AS credit_coach_commission,p.commission_coach,p.commission_level1,p.commission_level2,p.commission_level3 FROM public.products p WHERE p.status='active' AND p.price IS NOT NULL AND p.price>0;